import six
import struct
from google.protobuf.internal import decoder
from robot.api import logger

from . import ProtobufTypeId


class ProtobufDecoder(object):

    def __init__(self, definition):
        self.definition = definition
        self.protobuf_msg = ""
        self.dump = {}
        self.pos = 0
        self.value_decoders = {
            ProtobufTypeId.VARINT: self._decode_varint,
            ProtobufTypeId.FIXED_64: self._decode_fixed64,
            ProtobufTypeId.FIXED_32: self._decode_fixed32,
            ProtobufTypeId.LENGTH_DELIMITED: self._decode_bytes
        }
        self.errors = []

    def decode(self, protobuf_msg):
        """Decode protobuf message."""
        self.protobuf_msg = protobuf_msg
        self.dump = {}
        self.pos = 0
        self._create_empty_arrays()
        while self._next_param():
            self._decode_param()
        return self.dump

    def _create_empty_arrays(self):
        for param in self.definition.iter_parameters():
            if param.is_array():
                self.dump[param.name] = []

    def _next_param(self):
        return self.pos < len(self.protobuf_msg)

    def _decode_param(self):
        param_id, protobuf_type_id = self._decode_tag()
        raw_value = self.value_decoders[protobuf_type_id]()
        try:
            param = self.definition[param_id]
        except KeyError:
            logger.warn("Cannot decode object of class {}. No parameter with such ID: {}".format(self.definition.name, param_id))
            self.errors.append({"object": self.definition.name, "parameter": param_id, "error_msg": "No parameter with such ID"})
        else:
            self._decode_param_value(param, raw_value)

    def _decode_param_value(self, param, raw_value):
        if param.is_array():
            self._convert_array_value(param, raw_value)
        else:
            self.dump[param.name] = self._convert_param_value(param, raw_value)

    def _convert_array_value(self, param, value):
        if self._is_packed(param, value):
            self._convert_packed_array_values(param, value)
        else:
            self.dump[param.name].append(self._convert_param_value(param, value))

    def _is_packed(self, param, value):
        if isinstance(value, (six.string_types, six.binary_type)):
            if param.is_enum():
                return True
            if param.is_simple():
                return param.get_internal_type() in six.integer_types or param.get_internal_type() is float
        return False

    def _convert_packed_array_values(self, param, values):
        pos = 0
        while pos < len(values):
            value, pos = decoder._DecodeSignedVarint(values, pos)
            self.dump[param.name].append(self._convert_param_value(param, value))

    def _convert_param_value(self, param, value):
        if param.is_enum():
            return self._convert_enum_type(param, value)
        elif param.is_complex():
            return self._convert_complex_type(param, value)
        else:
            return self._convert_simple_type(param, value)

    def _decode_tag(self):
        tag = self._decode_varint()
        param_id = tag >> 3
        protobuf_type_id = tag & 0x7
        return param_id, protobuf_type_id

    def _decode_bytes(self):
        size = self._decode_varint()
        pos = self.pos
        self.pos += size
        return self.protobuf_msg[pos:self.pos]

    def _decode_varint(self):
        result, self.pos = decoder._DecodeSignedVarint(self.protobuf_msg, self.pos)
        return result

    def _decode_fixed64(self):
        pos = self.pos
        self.pos += 8
        return struct.unpack('<d', self.protobuf_msg[pos:self.pos])[0]

    def _decode_fixed32(self):
        pos = self.pos
        self.pos += 4
        return struct.unpack('<f', self.protobuf_msg[pos:self.pos])[0]

    @staticmethod
    def _decode_zigzag(value):
        return (value >> 1) ^ -(value & 1)

    def _convert_simple_type(self, param, value):
        if 'sint32' in str(param.protobuf_type):
            value = self._decode_zigzag(value)
        internal_type = param.get_internal_type()
        try:
            converted = internal_type(value)
            return param.value_modifier.apply(converted)
        except ValueError as e:
            logger.warn("Cannot decode parameter {} of {}: {}".format(param.name, self.definition.name, e))
            self.errors.append({"object": self.definition.name, "parameter": param.name, "error_msg": e, "value": value})
            return internal_type()

    def _convert_complex_type(self, param, value):
        definition = param.get_type_definition()
        if not isinstance(value, (six.string_types, six.binary_type)):
            logger.warn("Cannot decode complex parameter {} of {}. Input data is not basestring.".format(param.name, self.definition.name))
            self.errors.append({"object": self.definition.name, "parameter": param.name,
                                "error_msg": "Input data is not basestring", "value": value})
            return {}
        return ProtobufDecoder(definition).decode(value)

    def _convert_enum_type(self, param, value):
        definition = param.get_type_definition()
        if value not in definition.enum:
            logger.warn("Cannot decode enum parameter {} of {}. Invalid enum value: {!r}.".format(param.name, self.definition.name, value))
            self.errors.append(
                {"object": self.definition.name, "parameter": param.name, "error_msg": "Invalid enum value", "value": value})
            return value
        return definition.enum[value]
